// Rigtige geodata for Verbier og 4 Vallées-området, hentet fra OpenStreetMap via
// OpenSkiMap.org's åbne GeoJSON-datasæt (https://tiles.openskimap.org/geojson/).
// Alle lifter og pister herunder er ægte ruter fra det virkelige skiområde omkring
// Verbier, Bruson, Tortin og La Tzoumaz - filtreret ned til et område omkring Verbier.

// Startvisning for kortet - centreret om Médran/Attelas-omraadet, hvor man kan
// panorere/zoome ud for at se hele det tilknyttede liftnetværk (Bruson, Tortin, Tzoumaz).
export const verbierRegion = {
  latitude: 46.095,
  longitude: 7.245,
  latitudeDelta: 0.14,
  longitudeDelta: 0.18,
};

// Byer/landsbyer i omraadet - rigtige koordinater (Nominatim/OpenStreetMap).
// Vises som tekst-labels på det flade snekort, siden vi ikke længere bruger
// Apple/Googles baggrundskort (og dermed heller ikke deres indbyggede bynavne).
export const towns = [
  { id: 'verbier', name: 'Verbier', latitude: 46.09610, longitude: 7.22868 },
  { id: 'lechable', name: 'Le Châble', latitude: 46.08015, longitude: 7.21250 },
  { id: 'bruson', name: 'Bruson', latitude: 46.06621, longitude: 7.21863 },
  { id: 'latzoumaz', name: 'La Tzoumaz', latitude: 46.14444, longitude: 7.23489 },
];

